test("calculates interest as principal times rate times days over 365 with start included and end excluded, rounded to 2 decimals", function () {
  var actual = code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2026-03-01",
    endDate: "2026-04-01"
  });
  assert.deepEqual(actual, { days: 31, interest: 50.96 });
});

test("keeps the divisor at 365 in a leap year even when the period contains 29 February", function () {
  var actual = code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2028-02-01",
    endDate: "2028-03-01"
  });
  assert.deepEqual(actual, { days: 29, interest: 47.67 });
});

test("returns 0 days and 0.00 interest when the start date and end date are the same", function () {
  var actual = code.simpleInterest({
    principal: 10000.00,
    annualRate: 0.06,
    startDate: "2026-03-01",
    endDate: "2026-03-01"
  });
  assert.deepEqual(actual, { days: 0, interest: 0.00 });
});
